#include <stdio.h>
#include <string.h>

int main(int argc, char **argv) {
    // If no argument is provided, the original program considered the input
    // trivially balanced.
    if (argc < 2) {
        puts("BALANCED");
        return 0;
    }

    const char *input = argv[1];
    // The original binary used a fixed‑size stack (max 0x1ff entries).
    // 512 is sufficient and matches the observed limit.
    char stack[512];
    int sp = 0;               // stack pointer (number of items)
    int balanced = 1;         // 1 = still balanced, 0 = found mismatch

    for (size_t i = 0; input[i] != '\0'; ++i) {
        char c = input[i];
        if (c == '(' || c == '[' || c == '{') {
            if (sp >= (int)sizeof(stack)) { // overflow – treat as unbalanced
                balanced = 0;
                break;
            }
            stack[sp++] = c;               // push opening bracket
        } else if (c == ')' || c == ']' || c == '}') {
            if (sp == 0) {                 // closing without matching opening
                balanced = 0;
                break;
            }
            char open = stack[--sp];        // pop and compare
            if ((c == ')' && open != '(') ||
                (c == ']' && open != '[') ||
                (c == '}' && open != '{')) {
                balanced = 0;
                break;
            }
        }
        // any other characters are ignored – the original program only
        // examined the three bracket types.
    }

    // After processing all characters the stack must be empty for a true
    // balanced string.
    if (balanced && sp == 0) {
        puts("BALANCED");
    } else {
        puts("UNBALANCED");
    }
    return 0;
}
}
